import { Button } from '@/components/ui/button'
import { User, LogOut, Mountain, Package, MapPin } from 'lucide-react'
import { Link, useLocation } from 'react-router-dom'
import { useAuth } from '@/contexts/AuthContext'

interface AppHeaderProps {
  title?: string
  subtitle?: string
  icon?: React.ReactNode
  backTo?: string
  isDashboard?: boolean
  rightContent?: React.ReactNode
}

export function AppHeader({
  title = 'BetterPack',
  subtitle,
  icon,
  backTo = '/dashboard',
  isDashboard = false,
  rightContent
}: AppHeaderProps) {
  const { user, signOut } = useAuth()
  const location = useLocation()

  return (
    <header className="bg-white border-b border-border/40 sticky top-0 z-50 backdrop-blur-sm" role="banner">
      <nav className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8" role="navigation">
        <div className="flex justify-between items-center h-16">
          {/* Left section - Navigation */}
          <div className="flex items-center space-x-3 flex-1 min-w-0">
            {/* Mountain icon - always links to dashboard */}
            <Link
              to="/dashboard"
              className="p-2 sm:p-2 bg-primary/10 rounded-lg hover:opacity-80 transition-opacity flex-shrink-0 flex items-center justify-center"
            >
              <Mountain className="h-5 w-5 text-primary" />
            </Link>

            {/* Title - BetterPack on dashboard, page name elsewhere */}
            <div className="flex items-center space-x-4">
              <h1 className="text-lg sm:text-xl font-semibold tracking-tight">
                {isDashboard ? 'BetterPack' : title}
              </h1>

              {/* Navigation links - only show on non-dashboard pages */}
              {!isDashboard && user && (
                <nav className="hidden md:flex items-center space-x-1">
                  <Link
                    to="/gear"
                    className={`flex items-center space-x-1 px-3 py-1.5 rounded-md text-sm transition-colors ${
                      location.pathname === '/gear'
                        ? 'bg-primary/10 text-primary font-medium'
                        : 'text-muted-foreground hover:text-foreground hover:bg-muted'
                    }`}
                  >
                    <Package className="h-4 w-4" />
                    <span>Gear</span>
                  </Link>
                  <Link
                    to="/lists"
                    className={`flex items-center space-x-1 px-3 py-1.5 rounded-md text-sm transition-colors ${
                      location.pathname === '/lists'
                        ? 'bg-primary/10 text-primary font-medium'
                        : 'text-muted-foreground hover:text-foreground hover:bg-muted'
                    }`}
                  >
                    <MapPin className="h-4 w-4" />
                    <span>Lists</span>
                  </Link>
                </nav>
              )}
            </div>

            {subtitle && (
              <p className="text-xs text-muted-foreground truncate hidden sm:block">
                {subtitle}
              </p>
            )}
          </div>

          {/* Right section - Custom content and user actions */}
          <div className="flex items-center space-x-2 flex-shrink-0">
            {rightContent}

            {/* Always show user actions when logged in */}
            {user && (
              <div className="flex items-center space-x-1 sm:space-x-2">
                {/* Profile info - icon on mobile, full info on desktop */}
                <div className="flex items-center space-x-2 text-sm text-muted-foreground">
                  <User className="h-4 w-4" />
                  <span className="hidden sm:inline">{user.email}</span>
                </div>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={signOut}
                  className="text-muted-foreground hover:text-foreground transition-colors duration-150 min-h-[44px]"
                >
                  <LogOut className="h-4 w-4 sm:mr-2" />
                  <span className="hidden sm:inline">Sign out</span>
                </Button>
              </div>
            )}
          </div>
        </div>
      </nav>
    </header>
  )
}

