import { CollectionCompactRow, type CompactRowAction } from '@/components/shared/CollectionCompactRow'
import { Edit2, Trash2, Copy, Eye } from 'lucide-react'
import type { List, GearItem, WeightUnit } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

interface ListCompactRowProps {
  list: List
  gearItems: GearItem[]
  weightUnit: WeightUnit
  onView: (list: List) => void
  onEdit: (list: List) => void
  onDelete: (list: List) => void
  onDuplicate: (list: List) => void
  onClick?: (list: List) => void
}

export function ListCompactRow({
  list,
  gearItems,
  weightUnit,
  onView,
  onEdit,
  onDelete,
  onDuplicate,
  onClick
}: ListCompactRowProps) {
  // Calculate stats
  const itemCount = list.gear_ids?.length || 0
  const totalWeight = list.gear_ids?.reduce((sum, gearId) => {
    const item = gearItems.find(g => g.id === gearId)
    return sum + (item ? item.weight_grams * item.quantity : 0)
  }, 0) || 0

  // Build subtitle from description
  const subtitle = list.description || undefined

  // Data columns for compact view: Items, Weight
  const columns = [
    itemCount, // Items count
    formatWeightWithUnit(totalWeight, weightUnit) // Total weight
  ]

  // Build actions
  const actions: CompactRowAction[] = [
    {
      label: 'View',
      icon: <Eye className="mr-2 h-4 w-4" />,
      onClick: () => onView(list)
    },
    {
      label: 'Edit',
      icon: <Edit2 className="mr-2 h-4 w-4" />,
      onClick: () => onEdit(list)
    },
    {
      label: 'Duplicate',
      icon: <Copy className="mr-2 h-4 w-4" />,
      onClick: () => onDuplicate(list)
    },
    {
      label: 'Delete',
      icon: <Trash2 className="mr-2 h-4 w-4" />,
      onClick: () => onDelete(list),
      variant: 'destructive' as const
    }
  ]

  return (
    <CollectionCompactRow
      title={list.name}
      subtitle={subtitle}
      columns={columns}
      actions={actions}
      onClick={onClick ? () => onClick(list) : undefined}
    />
  )
}

