import { useState, useMemo, useCallback } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { ListDetailView } from '@/components/lists/ListDetailView'
import { ListCard } from '@/components/lists/ListCard'
import { ListRow } from '@/components/lists/ListRow'
import { ListCompactRow } from '@/components/lists/ListCompactRow'
import { CollectionTable } from '@/components/shared/CollectionTable'
import { CreateListFormWrapper } from '@/components/lists/CreateListFormWrapper'
import { EditListFormWrapper } from '@/components/lists/EditListFormWrapper'
import { DeleteListDialog } from '@/components/lists/DeleteListDialog'
import { CollectionPage } from '@/components/shared/CollectionPage'
import { ViewModeSelector, type ViewMode } from '@/components/shared/ViewModeSelector'
import { useViewMode } from '@/hooks/shared/useViewMode'
import { Button } from '@/components/ui/button'
import { ArrowLeft, Package } from 'lucide-react'
import { useLists, useCreateList, useUpdateList, useDeleteList, useDuplicateList } from '@/hooks/useListData'
import { useGearItems } from '@/hooks/useGearData'
import type { List, WeightUnit, GearItem } from '@/types/database'
import { formatWeightWithUnit } from '@/utils/weight'

export function ListsPage() {
  const { user } = useAuth()
  const [selectedList, setSelectedList] = useState<List | null>(null)
  const [searchTerm, setSearchTerm] = useState('')
  const [showCreateForm, setShowCreateForm] = useState(false)
  const [editingList, setEditingList] = useState<List | null>(null)
  const [deletingList, setDeletingList] = useState<List | null>(null)
  const weightUnit: WeightUnit = 'g' // Default weight unit for lists

  const [viewMode, setViewMode] = useViewMode('listsViewMode')

  // Data fetching
  const { data: lists = [], isLoading: listsLoading } = useLists(user?.id)
  const { data: gearItems = [], isLoading: gearLoading } = useGearItems(user?.id)

  // Mutations
  const createListMutation = useCreateList(user?.id)
  const updateListMutation = useUpdateList(user?.id)
  const deleteListMutation = useDeleteList(user?.id)
  const duplicateListMutation = useDuplicateList(user?.id)


  const handleCreateList = useCallback(async (data: Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>) => {
    await createListMutation.mutateAsync(data)
    setShowCreateForm(false)
  }, [createListMutation])

  const handleEditList = useCallback(async (id: string, updates: Partial<Omit<List, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => {
    await updateListMutation.mutateAsync({ id, updates })
    setEditingList(null)
  }, [updateListMutation])

  const handleDeleteList = useCallback(async (list: List) => {
    await deleteListMutation.mutateAsync(list.id)
    setDeletingList(null)
    // If we're viewing the deleted list, go back to list view
    if (selectedList?.id === list.id) {
      setSelectedList(null)
    }
  }, [deleteListMutation, selectedList])

  const handleDuplicateList = useCallback(async (list: List) => {
    const newName = `${list.name} (Copy)`
    await duplicateListMutation.mutateAsync({ listId: list.id, newName })
  }, [duplicateListMutation])

  const handleViewList = useCallback((list: List) => {
    setSelectedList(list)
  }, [])

  const handleBackToLists = () => {
    setSelectedList(null)
  }


  // Filter lists based on search term
  const filteredLists = useMemo(() => {
    if (!searchTerm) return lists

    const searchLower = searchTerm.toLowerCase()
    return lists.filter(list =>
      list.name.toLowerCase().includes(searchLower)
    )
  }, [lists, searchTerm])

  const isLoading = listsLoading || gearLoading

  const renderItems = useCallback((items: List[], currentViewMode?: string) => {
    const mode = currentViewMode || viewMode

    if (mode === 'comfortable') {
      return (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {items.map((list) => (
            <ListCard
              key={list.id}
              list={list}
              gearItems={gearItems}
              weightUnit={weightUnit}
              onView={handleViewList}
              onEdit={setEditingList}
              onDelete={setDeletingList}
              onDuplicate={handleDuplicateList}
            />
          ))}
        </div>
      )
    }

    if (mode === 'compact') {
      // Compact view - use simplified columns
      const compactColumns = [
        { 
          key: 'name', 
          label: 'Item', 
          sortable: true,
          sortValue: (list: List) => list.name
        },
        { 
          key: 'item_count', 
          label: 'Items', 
          hideOnMobile: true, 
          className: 'text-right', 
          sortable: true,
          sortValue: (list: List) => list.gear_ids?.length || 0
        },
        { 
          key: 'total_weight', 
          label: 'Weight', 
          hideOnMobile: true, 
          className: 'text-right', 
          sortable: true,
          sortValue: (list: List) => {
            return list.gear_ids?.reduce((sum, gearId) => {
              const item = gearItems.find(g => g.id === gearId)
              return sum + (item ? item.weight_grams * item.quantity : 0)
            }, 0) || 0
          }
        },
        { key: 'actions', label: '', className: 'text-right' }
      ]

      // Calculate totals for compact view
      const totalItems = items.reduce((sum, list) => sum + (list.gear_ids?.length || 0), 0)
      const totalWeight = items.reduce((sum, list) => {
        return sum + (list.gear_ids?.reduce((listSum, gearId) => {
          const item = gearItems.find(g => g.id === gearId)
          return listSum + (item ? item.weight_grams * item.quantity : 0)
        }, 0) || 0)
      }, 0)

      const compactTotals = [
        totalItems, // Total items across all lists
        formatWeightWithUnit(totalWeight, weightUnit) // Total weight
      ]

      return (
        <CollectionTable<List>
          columns={compactColumns}
          items={items}
          defaultSortField="name"
          showTotals={true}
          totals={compactTotals}
          renderRow={(list) => (
            <ListCompactRow
              key={list.id}
              list={list}
              gearItems={gearItems}
              weightUnit={weightUnit}
              onView={handleViewList}
              onEdit={setEditingList}
              onDelete={setDeletingList}
              onDuplicate={handleDuplicateList}
            />
          )}
        />
      )
    }

    // Default view - use full table layout
    const columns = [
      { 
        key: 'name', 
        label: 'Item', 
        sortable: true,
        sortValue: (list: List) => list.name
      },
      { 
        key: 'item_count', 
        label: 'Items', 
        hideOnMobile: true, 
        className: 'text-right', 
        sortable: true,
        sortValue: (list: List) => list.gear_ids?.length || 0
      },
      { 
        key: 'total_weight', 
        label: 'Weight', 
        hideOnMobile: true, 
        className: 'text-right', 
        sortable: true,
        sortValue: (list: List) => {
          return list.gear_ids?.reduce((sum, gearId) => {
            const item = gearItems.find(g => g.id === gearId)
            return sum + (item ? item.weight_grams * item.quantity : 0)
          }, 0) || 0
        }
      },
      { key: 'actions', label: '', className: 'text-right' }
    ]

    // Calculate totals for default view
    const totalItems = items.reduce((sum, list) => sum + (list.gear_ids?.length || 0), 0)
    const totalWeight = items.reduce((sum, list) => {
      return sum + (list.gear_ids?.reduce((listSum, gearId) => {
        const item = gearItems.find(g => g.id === gearId)
        return listSum + (item ? item.weight_grams * item.quantity : 0)
      }, 0) || 0)
    }, 0)

    const defaultTotals = [
      totalItems, // Total items across all lists
      formatWeightWithUnit(totalWeight, weightUnit) // Total weight
    ]

    return (
      <CollectionTable<List>
        columns={columns}
        items={items}
        defaultSortField="name"
        showTotals={true}
        totals={defaultTotals}
        renderRow={(list) => (
          <ListRow
            key={list.id}
            list={list}
            gearItems={gearItems}
            weightUnit={weightUnit}
            onView={handleViewList}
            onEdit={setEditingList}
            onDelete={setDeletingList}
            onDuplicate={handleDuplicateList}
          />
        )}
      />
    )
  }, [gearItems, weightUnit, handleViewList, handleDuplicateList, viewMode])

  const renderModals = useCallback(() => (
    <>
      {/* Create Form */}
      {showCreateForm && (
        <CreateListFormWrapper
          isOpen={showCreateForm}
          onCreate={handleCreateList}
          onCancel={() => setShowCreateForm(false)}
        />
      )}

      {/* Edit Form */}
      {editingList && (
        <EditListFormWrapper
          isOpen={!!editingList}
          list={editingList}
          onEdit={handleEditList}
          onCancel={() => setEditingList(null)}
        />
      )}

      {/* Delete Dialog */}
      {deletingList && (
        <DeleteListDialog
          list={deletingList}
          onConfirm={() => handleDeleteList(deletingList)}
          onCancel={() => setDeletingList(null)}
        />
      )}
    </>
  ), [showCreateForm, editingList, deletingList, handleCreateList, handleEditList, handleDeleteList])

  // Show list detail view when a list is selected
  if (selectedList) {
    return (
      <div className="min-h-screen bg-background">
        <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 sm:py-10">
          <div className="mb-6">
            <Button
              variant="ghost"
              onClick={handleBackToLists}
              className="mb-4"
            >
              <ArrowLeft className="w-4 h-4 mr-2" />
              Back to Lists
            </Button>
          </div>

          <ListDetailView
            list={selectedList}
            gearItems={gearItems}
            onEditList={handleEditList}
            onDeleteList={(id) => handleDeleteList({ id } as List)}
            onBackToLists={handleBackToLists}
          />
        </main>
      </div>
    )
  }

  return (
    <CollectionPage<List>
      items={lists}
      filteredItems={filteredLists}
      loading={isLoading}
      title="Your Lists"
      searchTerm={searchTerm}
      onSearchChange={setSearchTerm}
      searchPlaceholder="Search lists..."
      emptyState={{
        icon: <Package className="h-12 w-12 text-muted-foreground mx-auto mb-4" />,
        title: 'No lists found',
        description: 'Try adjusting your search term',
        noItemsTitle: 'No lists yet',
        noItemsDescription: 'Create your first list to start organizing gear for different adventures and trips.',
        showAddButton: true,
        addButtonText: 'Create Your First List'
      }}
      renderItems={renderItems}
      onAdd={() => setShowCreateForm(true)}
      renderModals={renderModals}
      showFloatingActionButton={true}
      headerActionButton={{
        text: 'Create List',
        onClick: () => setShowCreateForm(true)
      }}
      viewMode={{
        current: viewMode,
        onChange: (mode: string) => setViewMode(mode as ViewMode),
        component: (
          <ViewModeSelector
            value={viewMode}
            onChange={setViewMode}
          />
        )
      }}
    />
  )
}

