import { test, expect } from '@playwright/test'

test.describe('List Management Flow', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the lists page
    await page.goto('/lists')
  })

  test('should create a new list', async ({ page }) => {
    // Click create list button
    await page.getByRole('button', { name: /create list/i }).first().click()

    // Fill in the list name
    await page.getByLabel(/list name/i).fill('Test Summer Backpacking List')

    // Submit the form
    await page.getByRole('button', { name: /create list/i }).last().click()

    // Verify list was created
    await expect(page.getByText('Test Summer Backpacking List')).toBeVisible()

    // Should show success message
    await expect(page.getByText(/list created/i)).toBeVisible()
  })

  test('should display empty state when no lists exist', async ({ page }) => {
    // Assuming user has no lists, should see empty state
    await expect(page.getByText(/no lists yet/i)).toBeVisible()
    await expect(page.getByText(/create your first list/i)).toBeVisible()
  })

  test('should edit an existing list', async ({ page }) => {
    // First create a list to edit
    await page.getByRole('button', { name: /create list/i }).first().click()
    await page.getByLabel(/list name/i).fill('Original List Name')
    await page.getByRole('button', { name: /create list/i }).last().click()

    // Wait for list to be created
    await expect(page.getByText('Original List Name')).toBeVisible()

    // Click edit button (assuming it's visible on hover or in dropdown)
    await page.hover('text=Original List Name')
    await page.getByRole('button', { name: /edit/i }).click()

    // Update the name
    await page.getByLabel(/list name/i).clear()
    await page.getByLabel(/list name/i).fill('Updated List Name')

    // Submit the update
    await page.getByRole('button', { name: /update list/i }).click()

    // Verify the list name was updated
    await expect(page.getByText('Updated List Name')).toBeVisible()
    await expect(page.getByText('Original List Name')).not.toBeVisible()
  })

  test('should delete a list', async ({ page }) => {
    // First create a list to delete
    await page.getByRole('button', { name: /create list/i }).first().click()
    await page.getByLabel(/list name/i).fill('List to Delete')
    await page.getByRole('button', { name: /create list/i }).last().click()

    // Wait for list to be created
    await expect(page.getByText('List to Delete')).toBeVisible()

    // Click delete button
    await page.hover('text=List to Delete')
    await page.getByRole('button', { name: /delete/i }).click()

    // Confirm deletion in dialog
    await expect(page.getByText(/delete list/i)).toBeVisible()
    await expect(page.getByText(/this action cannot be undone/i)).toBeVisible()
    await page.getByRole('button', { name: /delete/i }).last().click()

    // Verify list was deleted
    await expect(page.getByText('List to Delete')).not.toBeVisible()
    await expect(page.getByText(/list deleted/i)).toBeVisible()
  })

  test('should duplicate a list', async ({ page }) => {
    // First create a list to duplicate
    await page.getByRole('button', { name: /create list/i }).first().click()
    await page.getByLabel(/list name/i).fill('Original List')
    await page.getByRole('button', { name: /create list/i }).last().click()

    // Wait for list to be created
    await expect(page.getByText('Original List')).toBeVisible()

    // Click duplicate button
    await page.hover('text=Original List')
    await page.getByRole('button', { name: /duplicate/i }).click()

    // Should see dialog asking for new name
    await expect(page.getByText(/duplicate list/i)).toBeVisible()
    await page.getByLabel(/new name/i).fill('Copy of Original List')
    await page.getByRole('button', { name: /duplicate/i }).last().click()

    // Should now see both lists
    await expect(page.getByText('Original List')).toBeVisible()
    await expect(page.getByText('Copy of Original List')).toBeVisible()
  })

  test('should navigate to list detail view', async ({ page }) => {
    // First create a list
    await page.getByRole('button', { name: /create list/i }).first().click()
    await page.getByLabel(/list name/i).fill('Detail Test List')
    await page.getByRole('button', { name: /create list/i }).last().click()

    // Wait for list to be created
    await expect(page.getByText('Detail Test List')).toBeVisible()

    // Click on the list or view button to navigate to detail
    await page.getByText('Detail Test List').click()

    // Should be on the list detail page
    await expect(page).toHaveURL(/\/lists\/[\w-]+/)
    await expect(page.getByRole('heading', { name: 'Detail Test List' })).toBeVisible()
  })

  test('should show list weight calculations', async ({ page }) => {
    // This test assumes there's gear data to work with
    // Would need to be adjusted based on actual implementation

    // First create a list
    await page.getByRole('button', { name: /create list/i }).first().click()
    await page.getByLabel(/list name/i).fill('Weight Test List')
    await page.getByRole('button', { name: /create list/i }).last().click()

    // Navigate to detail view
    await page.getByText('Weight Test List').click()

    // Should show weight information (0g initially for empty list)
    await expect(page.getByText(/total weight/i)).toBeVisible()
    await expect(page.getByText(/0g|0 items/)).toBeVisible()
  })
})

